  hk_bx_mul(lo7, hi7, L7, lo8, hi8, L8, &lo9, &hi9, &L9);
  hk_real lo10, hi10, L10;
  hk_bx_exp(lo9, hi9, L9, &lo10, &hi10, &L10);
  hk_real lo11, hi11, L11;
  hk_bx_sub(lo4, hi4, L4, lo10, hi10, L10, &lo11, &hi11, &L11);
