  hk_bx_div(lo11, hi11, L11, lo13, hi13, L13, &lo14, &hi14, &L14);
  hk_real lo15, hi15, L15;
  hk_bx_ite(lo3, hi3, lo6, hi6, L6, lo14, hi14, L14, &lo15, &hi15, &L15);
  hk_olo[0] = lo15; hk_ohi[0] = hi15; hk_oL[0] = L15;
