  lo2 = HK_LIT(2); hi2 = HK_LIT(2); L2 = HK_LIT(0);
  hk_real lo3, hi3, L3;
  hk_bx_div(lo0, hi0, L0, lo2, hi2, L2, &lo3, &hi3, &L3);
  hk_real lo4, hi4, L4;
  hk_bx_div(lo1, hi1, L1, lo0, hi0, L0, &lo4, &hi4, &L4);
