  const hk_real t13 = (t5 / t12);
  const hk_real d13 = ((d5 * t12 - t5 * d12) / (t12 * t12));
  const hk_real t14 = (t6 / t12);
  const hk_real d14 = ((d6 * t12 - t6 * d12) / (t12 * t12));
  const hk_real t15 = (t2 / t12);
  const hk_real d15 = ((d2 * t12 - t2 * d12) / (t12 * t12));
  hk_out[0] = t13;
  hk_dout[0] = d13;
  hk_out[1] = t14;
  hk_dout[1] = d14;
  hk_out[2] = t15;
