  const hk_real d10 = (d7 * t1 + t7 * d1);
  const hk_real t11 = (t8 * t2);
  const hk_real d11 = (d8 * t2 + t8 * d2);
  const hk_real t12 = (t10 - t11);
  const hk_real d12 = (d10 - d11);
  const hk_real t13 = (t7 * t4);
  const hk_real d13 = (d7 * t4 + t7 * d4);
  const hk_real t14 = (t8 * t5);
  const hk_real d14 = (d8 * t5 + t8 * d5);
  const hk_real t15 = (t13 - t14);
  const hk_real d15 = (d13 - d14);
  const hk_real t16 = (t12 * t15);
  const hk_real d16 = (d12 * t15 + t12 * d15);
  const hk_real t17 = (t8 * t1);
  const hk_real d17 = (d8 * t1 + t8 * d1);
  const hk_real t18 = (t7 * t2);
  const hk_real d18 = (d7 * t2 + t7 * d2);
  const hk_real t19 = (t17 + t18);
  const hk_real d19 = (d17 + d18);
  const hk_real t20 = (t8 * t4);
  const hk_real d20 = (d8 * t4 + t8 * d4);
  const hk_real t21 = (t7 * t5);
  const hk_real d21 = (d7 * t5 + t7 * d5);
  const hk_real t22 = (t20 + t21);
  const hk_real d22 = (d20 + d21);
  const hk_real t23 = (t19 * t22);
  const hk_real d23 = (d19 * t22 + t19 * d22);
  const hk_real t24 = (t16 + t23);
  const hk_real d24 = (d16 + d23);
  const hk_real t25 = (t24 + t9);
  const hk_real d25 = (d24 + d9);
  const hk_real t26 = (t1 * t4);
  const hk_real d26 = (d1 * t4 + t1 * d4);
  const hk_real t27 = (t2 * t5);
  const hk_real d27 = (d2 * t5 + t2 * d5);
  const hk_real t28 = (t26 + t27);
  const hk_real d28 = (d26 + d27);
  const hk_real t29 = (t28 + t9);
  const hk_real d29 = (d28 + d9);
  const bool t30 = hk_eq(t25, t29);
