  hk_bx_sqrt(lo4, hi4, HK_LIT(0), &lo5, &hi5, &hk_bx_void);
  hk_real lo6, hi6;
  hk_bx_sub(lo0, hi0, HK_LIT(0), lo5, hi5, HK_LIT(0), &lo6, &hi6, &hk_bx_void);
  hk_real lo7, hi7;
  lo7 = HK_LIT(2); hi7 = HK_LIT(2);
  hk_real lo8, hi8;
  hk_bx_div(lo0, hi0, HK_LIT(0), lo7, hi7, HK_LIT(0), &lo8, &hi8, &hk_bx_void);
  hk_real lo9, hi9;
  hk_bx_sub(lo8, hi8, HK_LIT(0), lo6, hi6, HK_LIT(0), &lo9, &hi9, &hk_bx_void);
  hk_real lo10, hi10;
  lo10 = HK_LIT(0); hi10 = HK_LIT(0);
  hk_real lo11, hi11;
  hk_bx_div(lo10, hi10, HK_LIT(0), lo0, hi0, HK_LIT(0), &lo11, &hi11, &hk_bx_void);
  hk_real lo12, hi12;
  hk_bx_asin(lo11, hi11, HK_LIT(0), &lo12, &hi12, &hk_bx_void);
  hk_real lo13, hi13;
  hk_bx_trig(0, lo12, hi12, HK_LIT(0), &lo13, &hi13, &hk_bx_void);
  hk_real lo14, hi14;
  hk_bx_mul(lo7, hi7, HK_LIT(0), lo13, hi13, HK_LIT(0), &lo14, &hi14, &hk_bx_void);
  hk_real lo15, hi15;
  hk_bx_div(lo0, hi0, HK_LIT(0), lo14, hi14, HK_LIT(0), &lo15, &hi15, &hk_bx_void);
  hk_real lo16, hi16;
  hk_bx_sub(lo0, hi0, HK_LIT(0), lo15, hi15, HK_LIT(0), &lo16, &hi16, &hk_bx_void);
  hk_real lo17, hi17;
  hk_bx_sub(lo16, hi16, HK_LIT(0), lo6, hi6, HK_LIT(0), &lo17, &hi17, &hk_bx_void);
  hk_real lo18, hi18;
  hk_bx_eq(lo9, hi9, lo17, hi17, &lo18, &hi18);
