  hk_real lo10, hi10;
  hk_bx_eq(lo2, hi2, lo9, hi9, &lo10, &hi10);
  hk_real lo11, hi11;
  hk_bx_mul(lo1, hi1, HK_LIT(0), lo5, hi5, HK_LIT(0), &lo11, &hi11, &hk_bx_void);
