  hk_bx_sub(lo11, hi11, HK_LIT(0), lo3, hi3, HK_LIT(0), &lo12, &hi12, &hk_bx_void);
  hk_real lo13, hi13;
  hk_bx_eq(lo1, hi1, lo12, hi12, &lo13, &hi13);
  hk_real lo14, hi14;
  hk_bx_mul(lo2, hi2, HK_LIT(0), lo5, hi5, HK_LIT(0), &lo14, &hi14, &hk_bx_void);
  hk_real lo15, hi15;
  hk_bx_sub(lo3, hi3, HK_LIT(0), lo14, hi14, HK_LIT(0), &lo15, &hi15, &hk_bx_void);
  hk_real lo16, hi16;
  hk_bx_eq(lo2, hi2, lo15, hi15, &lo16, &hi16);
  hk_real lo17, hi17;
  hk_bx_and(lo13, hi13, lo16, hi16, &lo17, &hi17);
  hk_real lo18, hi18;
  hk_bx_and(lo10, hi10, lo17, hi17, &lo18, &hi18);
