  lo3 = hk_lo[3]; hi3 = hk_hi[3];
  hk_real lo4, hi4;
  lo4 = hk_lo[4]; hi4 = hk_hi[4];
  hk_real lo5, hi5;
  hk_bx_mul(lo1, hi1, HK_LIT(0), lo2, hi2, HK_LIT(0), &lo5, &hi5, &hk_bx_void);
  hk_real lo6, hi6;
  lo6 = HK_LIT(0); hi6 = HK_LIT(0);
  hk_real lo7, hi7;
  hk_bx_le(lo6, hi6, lo1, hi1, &lo7, &hi7);
  hk_real lo8, hi8;
  hk_bx_le(lo6, hi6, lo2, hi2, &lo8, &hi8);
  hk_real lo9, hi9;
  hk_bx_lt(lo6, hi6, lo3, hi3, &lo9, &hi9);
  hk_real lo10, hi10;
  hk_bx_mul(lo0, hi0, HK_LIT(0), lo3, hi3, HK_LIT(0), &lo10, &hi10, &hk_bx_void);
  hk_real lo11, hi11;
  hk_bx_le(lo5, hi5, lo10, hi10, &lo11, &hi11);
  hk_real lo12, hi12;
  hk_bx_trig(1, lo4, hi4, HK_LIT(0), &lo12, &hi12, &hk_bx_void);
  hk_real lo13, hi13;
  hk_bx_mul(lo5, hi5, HK_LIT(0), lo12, hi12, HK_LIT(0), &lo13, &hi13, &hk_bx_void);
  hk_real lo14, hi14;
  hk_bx_div(lo13, hi13, HK_LIT(0), lo3, hi3, HK_LIT(0), &lo14, &hi14, &hk_bx_void);
  hk_real lo15, hi15;
  hk_bx_le(lo14, hi14, lo0, hi0, &lo15, &hi15);
  hk_real lo16, hi16;
  { hk_real n0, n1; hk_bx_not(lo11, hi11, &n0, &n1); hk_bx_or(n0, n1, lo15, hi15, &lo16, &hi16); }
  hk_real lo17, hi17;
  { hk_real n0, n1; hk_bx_not(lo9, hi9, &n0, &n1); hk_bx_or(n0, n1, lo16, hi16, &lo17, &hi17); }
  hk_real lo18, hi18;
  { hk_real n0, n1; hk_bx_not(lo8, hi8, &n0, &n1); hk_bx_or(n0, n1, lo17, hi17, &lo18, &hi18); }
  hk_real lo19, hi19;
  { hk_real n0, n1; hk_bx_not(lo7, hi7, &n0, &n1); hk_bx_or(n0, n1, lo18, hi18, &lo19, &hi19); }
  hk_olo[0] = lo19; hk_ohi[0] = hi19; hk_oL[0] = HK_TRUTH;
