  hk_real lo5, hi5;
  hk_bx_pow(lo4, hi4, HK_LIT(0), 2, &lo5, &hi5, &hk_bx_void);
  hk_real lo6, hi6;
  hk_bx_sub(lo3, hi3, HK_LIT(0), lo1, hi1, HK_LIT(0), &lo6, &hi6, &hk_bx_void);
  hk_real lo7, hi7;
  hk_bx_pow(lo6, hi6, HK_LIT(0), 2, &lo7, &hi7, &hk_bx_void);
  hk_real lo8, hi8;
  hk_bx_add(lo5, hi5, HK_LIT(0), lo7, hi7, HK_LIT(0), &lo8, &hi8, &hk_bx_void);
  hk_real lo9, hi9;
  hk_bx_mul(lo0, hi0, HK_LIT(0), lo3, hi3, HK_LIT(0), &lo9, &hi9, &hk_bx_void);
  hk_real lo10, hi10;
  hk_bx_mul(lo1, hi1, HK_LIT(0), lo2, hi2, HK_LIT(0), &lo10, &hi10, &hk_bx_void);
  hk_real lo11, hi11;
  hk_bx_sub(lo9, hi9, HK_LIT(0), lo10, hi10, HK_LIT(0), &lo11, &hi11, &hk_bx_void);
  hk_real lo12, hi12;
  lo12 = HK_LIT(0); hi12 = HK_LIT(0);
  hk_real lo13, hi13;
  hk_bx_lt(lo12, hi12, lo8, hi8, &lo13, &hi13);
  hk_real lo14, hi14;
  hk_bx_sqrt(lo8, hi8, HK_LIT(0), &lo14, &hi14, &hk_bx_void);
  hk_real lo15, hi15;
  hk_bx_div(lo11, hi11, HK_LIT(0), lo14, hi14, HK_LIT(0), &lo15, &hi15, &hk_bx_void);
  hk_real lo16, hi16;
  hk_bx_lt(lo12, hi12, lo15, hi15, &lo16, &hi16);
  hk_real lo17, hi17;
  hk_bx_lt(lo12, hi12, lo11, hi11, &lo17, &hi17);
