  const hk_real t25 = hk_sqrt(t24);
  const hk_real d25 = (d24 / (HK_LIT(2) * t25));
  const hk_real t26 = (t19 / t25);
  const hk_real d26 = ((d19 * t25 - t19 * d25) / (t25 * t25));
  const hk_real t27 = (t0 * t3);
  const hk_real d27 = (d0 * t3 + t0 * d3);
  const hk_real t28 = (t1 * t2);
  const hk_real d28 = (d1 * t2 + t1 * d2);
  const hk_real t29 = (t27 + t28);
  const hk_real d29 = (d27 + d28);
  const hk_real t30 = (t0 - t2);
  const hk_real d30 = (d0 - d2);
  const hk_real t31 = t30 * t30;
