  hk_bx_mul(lo11, hi11, HK_LIT(0), lo13, hi13, HK_LIT(0), &lo14, &hi14, &hk_bx_void);
  hk_real lo15, hi15;
  hk_bx_mul(lo4, hi4, HK_LIT(0), lo5, hi5, HK_LIT(0), &lo15, &hi15, &hk_bx_void);
  hk_real lo16, hi16;
  hk_bx_mul(lo2, hi2, HK_LIT(0), lo7, hi7, HK_LIT(0), &lo16, &hi16, &hk_bx_void);
  hk_real lo17, hi17;
  hk_bx_sub(lo15, hi15, HK_LIT(0), lo16, hi16, HK_LIT(0), &lo17, &hi17, &hk_bx_void);
  hk_real lo18, hi18;
  hk_bx_mul(lo8, hi8, HK_LIT(0), lo17, hi17, HK_LIT(0), &lo18, &hi18, &hk_bx_void);
  hk_real lo19, hi19;
  hk_bx_add(lo14, hi14, HK_LIT(0), lo18, hi18, HK_LIT(0), &lo19, &hi19, &hk_bx_void);
  hk_real lo20, hi20;
  hk_bx_mul(lo2, hi2, HK_LIT(0), lo6, hi6, HK_LIT(0), &lo20, &hi20, &hk_bx_void);
