  hk_bx_mul(lo8, hi8, HK_LIT(0), lo8, hi8, HK_LIT(0), &lo25, &hi25, &hk_bx_void);
  hk_real lo26, hi26;
  hk_bx_mul(lo1, hi1, HK_LIT(0), lo8, hi8, HK_LIT(0), &lo26, &hi26, &hk_bx_void);
  hk_real lo27, hi27;
  hk_bx_sub(lo25, hi25, HK_LIT(0), lo26, hi26, HK_LIT(0), &lo27, &hi27, &hk_bx_void);
  hk_real lo28, hi28;
  hk_bx_mul(lo27, hi27, HK_LIT(0), lo5, hi5, HK_LIT(0), &lo28, &hi28, &hk_bx_void);
  hk_real lo29, hi29;
  hk_bx_add(lo24, hi24, HK_LIT(0), lo28, hi28, HK_LIT(0), &lo29, &hi29, &hk_bx_void);
  hk_real lo30, hi30;
  hk_bx_mul(lo1, hi1, HK_LIT(0), lo11, hi11, HK_LIT(0), &lo30, &hi30, &hk_bx_void);
