  hk_real lo34, hi34;
  hk_bx_mul(lo8, hi8, HK_LIT(0), lo11, hi11, HK_LIT(0), &lo34, &hi34, &hk_bx_void);
  hk_real lo35, hi35;
  hk_bx_sub(lo9, hi9, HK_LIT(0), lo34, hi34, HK_LIT(0), &lo35, &hi35, &hk_bx_void);
